\label{rem:r_0=1}
\begin{enumerate}
\item[(1)]
In \cite{CNY}, we treated the case where $r_0=1$.
                                                                                         
                            
                                                                                             
                 
\item[(2)]
In \cite{Y:Stability}, we proved that
there is a constant $N$ depending on $r$ and $\langle v^2 \rangle$ such that
$D_{X'} \circ \Phi_{X \to X'}^{{\mathcal E}}(E) \in {\mathcal M}_{H'}(v')$ 
for all $E \in {\mathcal M}_H(v)$ if $d \geq N$.  
\begin{NB}
Since $\operatorname{Pic}(X)={\mathbb Z}H$, $H$ is a general polarization.
\end{NB}
           
                                                                  
                               
                                                                                                 
                                                                        
                                                     
                                                                               
                                                                                            
\end{enumerate}

For $v=(r,dH,a)$,
we set 
\begin{equation}
r^\beta=r,\;d^\beta=d-r\frac{q}{p},\; a^\beta=a-2nd\frac{q}{p}+rn\frac{q^2}{p^2}.
\end{equation}

For a Mukai vector $v=(r,d H,a)$ with 
$r \geq 0$, $d^\beta>0$ and $a^\beta \geq 0$,
let $D_v^\beta$ be the set of Mukai vectors
$v_1=(r_1,d_1 H,a_1)=e^\beta (r_1,d_1^\beta H,a_1^\beta)$ such that
                         
\begin{equation}
\langle v_1^2 \rangle=-2\epsilon\; (\epsilon=0,1),\;\;
d^\beta \geq d_1^\beta > 0,\;\;
\frac{a_1^\beta d^\beta-a^\beta d_1^\beta}{r_1 d^\beta-r d_1^\beta}>0
\end{equation}
and $r_1>r$ if $d_1^\beta=d^\beta$.

\label{rem:symmetry}
For $v_1=(r_1,d_1 H,a_1) \in D_v^\beta$,
$d_1^\beta=d^\beta$ implies $\frac{a_1^\beta-a^\beta}{r_1-r}>0$.
Hence we have a bijection
\begin{NB2}
\begin{equation}
\begin{matrix}
D_{e^\beta(r,d^\beta H,a^\beta)}^\beta & \to & 
D_{e^{\beta'}(r_0 a^{\beta'},d^{\beta'} H,r/r_0)}^{\beta'}\\
e^\beta(r_1,d_1^\beta H,a_1^\beta) & \mapsto & e^{\beta'}(r_0 a_1^{\beta'},d_1^{\beta'} H,r_1/r_0).
\end{matrix}
\end{equation}
\end{NB2}
\begin{equation}
\begin{matrix}
D_v^\beta & \to & 
D_{v'}^{\beta'}\\
v_1 & \mapsto & v_1',
\end{matrix}
\end{equation}
where
$v':=\Phi_{X \to X'}^{\mathcal E}(v)^{\vee}, v_1':=\Phi_{X \to X'}^{\mathcal E}(v_1)^{\vee}$.

Assume that $d_1=d$. If $r_1 d-rd_1>0$, then $r_1>rd_1/d=r$.
\begin{NB}
In this case, $C_\lambda$ passes $(0,t_0)$.
\end{NB}

(1)
We note that $r_1>0$. Then we see that 
\begin{equation}
\begin{split}
\langle v,v_1 \rangle =& 2nd^\beta d_1^\beta-r_1 a^\beta-r a_1^\beta \\
= & 2nd^\beta d_1^\beta-(a_1^\beta d^\beta-k)\frac{r_1}{d_1^\beta}-ra_1^\beta\\
=&\frac{d^\beta}{d_1^\beta}(n(d_1^\beta)^2-r_1 a_1^\beta)-ra_1^\beta +\frac{r_1 k}{d_1^\beta}
+nd^\beta d_1^\beta \\
=&-\frac{d^\beta}{d_1^\beta}\epsilon-\frac{r}{r_1}((d_1^\beta)^2 n+\epsilon)+
\frac{r_1 k}{d_1^\beta}+nd^\beta d_1^\beta \\
=& \frac{d^\beta}{d_1^\beta}(n(d_1^\beta)^2-\epsilon)-
\frac{1}{r_1 d_1^\beta}(rn (d_1^\beta)^3+rd_1^\beta \epsilon-k r_1^2)\\
                                     
                                                                        
=& \frac{1}{r_1 d_1^\beta}\left(
(r_1 d^\beta-r d_1^\beta)(n(d^\beta_1)^2-\epsilon)-(2rd_1^\beta \epsilon -k r_1^2) \right).
\end{split}
\end{equation}
 

(2)
Note that $k \geq 1/p^2$.
If $\epsilon=0$ and $n>p^2$, then
\begin{equation}\label{eq:e=0}
\begin{split}
\langle v,v_1 \rangle =  &
(r_1 d^\beta-r d_1^\beta)
n\frac{d_1^\beta}{r_1}+k\frac{r_1}{d_1^\beta}
\geq 2\sqrt{kn(r_1 d^\beta-r d_1^\beta)} > 2.
                                                 
       
                                                                    
                                   
\end{split}
\end{equation}

(3)
If $\langle v,v_1 \rangle=2$, then by the proof of (2), we see that
$r_1 d-rd_1=1$, $k=a_1 d-ad_1=1$ and $d_1=r_1$.
Then we have $r_1=d_1=1$, which implies $a_1=1$.
Hence we get $d=r+1=a+1$. Therefore $v=(r,(r+1)H,r)$ and $v_1=(1,H,1)$.

\label{lem:stability-cond}
If $(s,t) \in U_+^\beta (\nu)$, then
${\mathcal E}_{| X \times \{x' \}}^{\vee}$ is $\sigma_{(sH,tH)}$-stable for all $x' \in X'$.

\label{prop:no-wall}
The following conditions are equivalent. 
\begin{enumerate}
\item[(1)]
$\Phi_{X \to X'}^{{\mathcal E}}(E)^{\vee} \in {\mathcal M}_{H'}(v')$
for a general $E \in {\mathcal M}_H(r,dH,a)$.
\item[(2)]
$\langle v,v_1 \rangle \geq 0$
for $v_1=(r_1,d_1 H,a_1) \in D_v^\beta$ with $\langle v_1^2 \rangle=-2$
and $r_1 d-r d_1>0$.  
\end{enumerate}
Under the condition, we have a birational map
\begin{equation}
\begin{matrix}
{\mathcal M}_H(r,dH,a) & \cdots \to & {\mathcal M}_{H'}(v')\\
E & \mapsto & \Phi_{X \to X'}^{{\mathcal E}}(E)^{\vee} 
\end{matrix}
\end{equation}

\label{thm:n}
Let $v=(r,dH,a)$ be a Mukai vector such that
\begin{equation}\label{eq:cond-v}
r \geq 0, \; pd-rq>0,-\langle e^{\frac{q}{p}H}, v \rangle \geq 0,\;
\langle v^2 \rangle \geq -2.
\end{equation}
Assume that $n \geq (2r+p)p$.
Then
                  
            
$\Phi_{X \to X'}^{{\mathcal E}}(E)^{\vee} \in {\mathcal M}_{H'}(v')$
for a general $E \in {\mathcal M}_H(v) \setminus Z$, where 
$v'=\Phi_{X \to X'}^{{\mathcal E}}(v)$ and $Z$ is a closed substack of ${\mathcal M}_H(v)$. 
           
                         
                                   
                              
                  
      
                                                   
      
                      
                             
                
                
Moreover
$\dim Z \leq \dim {\mathcal M}_H(v)-2$ if $r>0$.

We set $k:=a_1^\beta d^\beta-a^\beta d_1^\beta$ as in Lemma \ref{lem:r_1>0}.

(1)
If $r_1 d^\beta-r d_1^\beta>0$, then we see that
\begin{equation}\label{eq:aCM:remark1}
\langle v,v_1 \rangle=\frac{2 d_1^\beta n}{r_1}(r_1 d^\beta-r d_1^\beta)+
\frac{r}{r_1}((d_1^\beta)^2 n-\epsilon)-r_1 a^\beta>0.
\end{equation}

If $r_1 d^\beta-r d_1^\beta<0$, then 
we get $k<0$, which implies $a_1<\frac{d_1^\beta}{d^\beta}a^\beta \leq 0$.
Hence we also get
$r_1<0$. 
By using \eqref{eq:r_1>0}, we get
\begin{equation}\label{eq:aCM:remark2}
\langle v,v_1 \rangle=
\frac{1}{-r_1 d_1^\beta}\left(
-(r_1 d^\beta-r d_1^\beta)(n(d^\beta_1)^2-\epsilon)+(2rd_1^\beta \epsilon -k r_1^2) \right)>0.
\end{equation}


(2)
We first assume that 
$r_1 d^\beta-r d_1^\beta<0$.
                                                        
Then $k<0$, $a_1^\beta<\frac{d_1^\beta}{d^\beta} a^\beta \leq 0$ and
$-k \geq 1/p^2$.
If $\epsilon=0$ and $n>p^2$, then
\begin{equation}
\begin{split}
\langle v,v_1 \rangle =  &
(r d_1^\beta-r_1 d^\beta)
n\frac{d_1^\beta}{-r_1}-k \frac{-r_1}{d_1^\beta}
\geq 2\sqrt{(-k) n(r d_1^\beta-r_1 d^\beta)} > 2.
                                                 
       
                                                                    
                                   
\end{split}
\end{equation}

We next assume that $r_1 d^\beta-r d_1^\beta>0$.
                                                     
Note that $r_1>r \frac{d_1^\beta}{d^\beta} \geq 0$ and
$k \geq 1/p^2$.
If $\epsilon=0$ and $n>p^2$, then
\begin{equation}
\begin{split}
\langle v,v_1 \rangle =  &
(r_1 d^\beta-r d_1^\beta)
n\frac{d_1^\beta}{r_1}+k \frac{r_1}{d_1^\beta}
\geq 2\sqrt{k n(r_1 d^\beta-r d_1^\beta)} > 2.
                                                 
       
                                                                    
                                   
\end{split}
\end{equation}

Assume that $n \geq 8$ and $n \equiv 1 \mod 4$.
Let $E_0$ be a stable vector bundle such that $v(E_0)=(2,qH,2\ell+1)$ with
$q<0$ and
$\ell=\frac{q^2 n-1}{4} \in {\mathbb Z}$.
Then 
we have a non-symplectic 
birational automorphism $\varphi$ of $X^{[\ell+1]}$:
\begin{equation}
\begin{matrix}
\varphi:& X^{[\ell+1]} & \to & X^{[\ell+1]}\\
& I_Z & \mapsto & \operatorname{coker}(I_Z^{\vee}(qH) \to E_0^{\vee}(qH)).
\end{matrix}
\end{equation} 
\begin{NB2}
$v(E_0)-v(I_Z)=(1,qH,3 \ell+1)=(1,0,-\ell)e^{qH}$.
\end{NB2}

\label{prop:p>s,t}
If there is a totally semistable wall on $s=\frac{q}{p}$, then there is a pair of positive integers
$s,t$ such that $n=st$, $\gcd(s,t)=1$ and $p>s,t$.

If there is a totally semistable wall on $s=\frac{q}{p}$, then
\cite[Cor. 5.13]{YY2} implies that
we have a decomposition
\begin{equation}\label{eq:v}
v=\delta(\ell_1 (p_1^2 s,p_1 q_1 H,q_1^2 t)-\ell_2 (p_2^2 t,p_2 q_2 H,q_2^2 s)),\;
p_1,p_2,q_1,q_2,s,t \in {\mathbb Z}
\end{equation}
 
such that $\delta=\pm 1$,
$\{\ell_1,\ell_2\}=\{1,\ell \}$,
$p_1 q_2 s-p_2 q_1 t=1$, $st=n$,
$p_1,p_2,s,t>0$ and
\begin{equation}\label{eq:pq}
\frac{q_1}{p_1 s}<\frac{q}{p}<\frac{q_2}{p_2 t}.
\end{equation}
 
Then
\begin{equation}\label{eq:p>s,t}
-p<p_1 s(p_2 qt-q_2 p)<
0<t p_2(p_1 q s-pq_1)<p.
\end{equation}
Hence $p>s,t$.

Assume that there is a totally semistable wall on $s=\frac{q}{p}$.
It is sufficient to prove that
$$
\left|d-\frac{q}{p}r \right| < p+\frac{r}{n}.
$$
We take the decomposition \eqref{eq:v}:
$$
(r,dH,a)=\delta(\ell_1 (p_1^2 s,p_1 q_1 H,q_1^2 t)-\ell_2 (p_2^2 t,p_2 q_2 H,q_2^2 s)).
$$
We first assume that $\delta=1$. Then
\begin{equation}
r=\ell_1 p_1^2 s-\ell_2 p_2^2 t,\;
d=\ell_1 p_1 q_1-\ell_2 p_2 q_2.
\end{equation}


We see that
\begin{equation}
d-\frac{q}{p}r=\ell_1 p_1 q_1-\ell_2 p_2 \frac{p_2 q_1 t+1}{p_1 s}-\frac{q}{p}r
=\left(\frac{q_1}{p_1 s}-\frac{q}{p} \right)r-\frac{\ell_2 p_2}{p_1 s}
\end{equation}
and
\begin{equation}
d-\frac{q}{p}r=\ell_1 p_1 \frac{q_2 p_1 s-1}{p_2 t}-\ell_2 p_2 q_2-\frac{q}{p}r
=\left(\frac{q_2}{p_2 t}-\frac{q}{p} \right)r-\frac{\ell_1 p_1}{p_2 t}.
\end{equation}

By \eqref{eq:pq}, 
\begin{equation}
0<\frac{q}{p}-\frac{q_1}{p_1 s}<\frac{1}{n p_1 p_2}, \; 
0<\frac{q_2}{p_2 t}-\frac{q}{p}<\frac{1}{n p_1 p_2}.
\end{equation}
Therefore
\begin{equation}
0>d-\frac{q}{p}r>-\frac{r}{n}-p.
\end{equation}


We next assume that $\delta=-1$, that is,
\begin{equation}
r=-\ell_1 p_1^2 s+\ell_2 p_2^2 t,\;
d=-\ell_1 p_1 q_1+\ell_2 p_2 q_2.
\end{equation}
In this case, we see that
\begin{equation}
d-\frac{q}{p}r=\ell_2 p_2 q_2-\ell_1 p_1 q_1-\frac{q}{p}r=
\left( \frac{q_1}{p_1 s}-\frac{q}{p}\right)r+\frac{\ell_2 p_2}{p_1 s}<\frac{\ell_2 p_2}{p_1 s}
\end{equation}
and
\begin{equation}
0<d-\frac{q}{p}r=\ell_2 p_2 q_2-\ell_1 p_1 q_1-\frac{q}{p}r=
\left( \frac{q_2}{p_2 t}-\frac{q}{p}\right)r+\frac{\ell_1 p_1}{p_2 t}<\frac{r}{p_1 p_2 n}+\frac{\ell_1 p_1}{p_2 t}.
\end{equation}

Therefore 
\begin{equation}
0<d-\frac{q}{p}r<\frac{r}{n}+p.
\end{equation}
